package fixture

import (
	"errors"
	"testing"
)

func TestOracleClamp(t *testing.T) {
	for _, c := range []struct{ x, low, high, want int }{
		{-5, -2, 4, -2}, {9, -2, 4, 4}, {1, -2, 4, 1},
		{-2, -2, 4, -2}, {4, -2, 4, 4}, {8, 3, 3, 3},
	} {
		got, err := Clamp(c.x, c.low, c.high)
		if err != nil || got != c.want {
			t.Errorf("Clamp(%d,%d,%d) = %d,%v; want %d,nil", c.x, c.low, c.high, got, err, c.want)
		}
	}
	if _, err := Clamp(0, 8, 2); !errors.Is(err, ErrRange) {
		t.Errorf("invalid range error = %v; want ErrRange", err)
	}
}

