func TestOracleMountedResponse(t *testing.T) {
	r := httptest.NewRecorder()
	Router().ServeHTTP(r, httptest.NewRequest(http.MethodGet, "/item", nil))
	if r.Code != 404 {
		t.Errorf("status = %d", r.Code)
	}
	if got := r.Header().Get("Content-Type"); got != "application/json" {
		t.Errorf("content type = %q", got)
	}
	if got := r.Header().Get("X-Request-ID"); got != "fixture-request" {
		t.Errorf("middleware header = %q", got)
	}
	if got := r.Body.String(); got != "{\"error\":\"not_found\"}\n" {
		t.Errorf("body = %q", got)
	}
}

