package fixture

import (
	"database/sql"
	"testing"
)

func TestOracleNullMapping(t *testing.T) {
	for _, c := range []struct {
		v    sql.NullString
		want *string
	}{
		{sql.NullString{String: "stale", Valid: false}, nil},
		{sql.NullString{}, nil},
		{sql.NullString{String: "", Valid: true}, oracleString("")},
		{sql.NullString{String: "car", Valid: true}, oracleString("car")},
	} {
		got := Label(c.v)
		if c.want == nil {
			if got != nil {
				t.Errorf("%+v: expected nil, got %q", c.v, *got)
			}
			continue
		}
		if got == nil || *got != *c.want {
			t.Errorf("%+v: expected non-nil %q, got %v", c.v, *c.want, got)
		}
	}
}
func oracleString(s string) *string { return &s }

