package fixture

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestOracleTenantEffect(t *testing.T) {
	for _, c := range []struct {
		tenant, header string
		status, writes int
	}{
		{"other", "owner", 403, 0}, {"", "owner", 403, 0},
		{"owner", "other", 204, 1}, {"owner", "", 204, 1},
	} {
		s := &Store{Tenant: "owner"}
		r := httptest.NewRequest(http.MethodPost, "/write", nil)
		r = r.WithContext(WithTenant(r.Context(), c.tenant))
		r.Header.Set("X-Tenant", c.header)
		w := httptest.NewRecorder()
		Handler(s).ServeHTTP(w, r)
		if w.Code != c.status || s.Writes != c.writes {
			t.Errorf("tenant=%q header=%q: status=%d writes=%d; want %d,%d", c.tenant, c.header, w.Code, s.Writes, c.status, c.writes)
		}
	}
	s := &Store{Tenant: "owner"}
	r := httptest.NewRequest(http.MethodPost, "/write", nil)
	r.Header.Set("X-Tenant", "owner")
	w := httptest.NewRecorder()
	Handler(s).ServeHTTP(w, r)
	if w.Code != 403 || s.Writes != 0 {
		t.Errorf("missing identity: status=%d writes=%d", w.Code, s.Writes)
	}
}

